// Helper: translate questions array based on language
import type { Language } from './LanguageContext'

const allTranslations: Record<Language, Record<string, QT>> = { en: {}, sv: quizSv, ko: quizKo }

export function translateQuestions(questions: Question[], lang: Language): Question[] {
  if (lang === 'en') return questions
  const t = allTranslations[lang] ?? {}
  return questions.map(q => {
    const tr = t[q.id]
    if (!tr) return q
    return {
      ...q,
      question: tr.question ?? q.question,
      options: tr.options ?? q.options,
      explanation: tr.explanation ?? q.explanation,
      modelAnswer: tr.modelAnswer ?? q.modelAnswer,
    }
  })
}

